type SortDirection = "ascending" | "descending"
type SortValue = string | number | bigint | boolean | Date | null | undefined

interface DataTableSort {
  columnId: string
  direction: SortDirection
}

interface DataTablePage<Row> {
  rows: Row[]
  page: number
  pageCount: number
  total: number
}

type SelectionState = "none" | "some" | "all"

const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: "base" })

function isMissing(value: SortValue): value is null | undefined {
  return value === null || value === undefined || (typeof value === "number" && Number.isNaN(value))
}

function compareSortValues(a: SortValue, b: SortValue): number {
  if (typeof a === "string" && typeof b === "string") return collator.compare(a, b)
  const left = a instanceof Date ? a.getTime() : a
  const right = b instanceof Date ? b.getTime() : b
  if (left === right) return 0
  return (left as number) < (right as number) ? -1 : 1
}

// Missing values sort last in both directions, so a descending sort doesn't open on a page of blanks.
function sortRows<Row>(
  rows: readonly Row[],
  sort: DataTableSort | null | undefined,
  sortValue: ((row: Row) => SortValue) | undefined,
): Row[] {
  if (!sort || !sortValue) return [...rows]
  const sign = sort.direction === "ascending" ? 1 : -1
  return rows
    .map((row, index) => ({ row, index, value: sortValue(row) }))
    .toSorted((a, b) => {
      const missingA = isMissing(a.value)
      const missingB = isMissing(b.value)
      if (missingA || missingB) return missingA === missingB ? a.index - b.index : missingA ? 1 : -1
      return sign * compareSortValues(a.value, b.value) || a.index - b.index
    })
    .map((entry) => entry.row)
}

function nextSort(current: DataTableSort | null | undefined, columnId: string): DataTableSort {
  if (current?.columnId === columnId && current.direction === "ascending") return { columnId, direction: "descending" }
  return { columnId, direction: "ascending" }
}

function pageCountOf(total: number, pageSize: number | undefined): number {
  if (!pageSize || pageSize <= 0 || !Number.isFinite(pageSize)) return 1
  return Math.max(1, Math.ceil(total / pageSize))
}

function clampPage(page: number, pageCount: number): number {
  if (!Number.isFinite(page)) return 1
  return Math.min(Math.max(1, Math.trunc(page)), pageCount)
}

function paginate<Row>(rows: readonly Row[], page: number, pageSize: number | undefined): DataTablePage<Row> {
  const total = rows.length
  const pageCount = pageCountOf(total, pageSize)
  const current = clampPage(page, pageCount)
  if (pageCount === 1) return { rows: [...rows], page: current, pageCount, total }
  const size = pageSize as number
  return { rows: rows.slice((current - 1) * size, current * size), page: current, pageCount, total }
}

function selectionState(ids: readonly string[], selected: ReadonlySet<string>): SelectionState {
  if (ids.length === 0) return "none"
  const count = ids.reduce((sum, id) => sum + (selected.has(id) ? 1 : 0), 0)
  if (count === 0) return "none"
  return count === ids.length ? "all" : "some"
}

function toggleIds(selected: readonly string[], ids: readonly string[], checked: boolean): string[] {
  const next = new Set(selected)
  for (const id of ids) {
    if (checked) next.add(id)
    else next.delete(id)
  }
  return [...next]
}

export { clampPage, compareSortValues, nextSort, pageCountOf, paginate, selectionState, sortRows, toggleIds }
export type { DataTablePage, DataTableSort, SelectionState, SortDirection, SortValue }

import { createChange, createController, definePrimitive, type ChangeDetails, type ChangeOptions } from "@ui-sdk/core"

import { toggleIds, type DataTableSort, type SortDirection } from "@/lib/data-table-model"

type DataTableSortChangeReason = "item-press" | "imperative"
type DataTableSelectionChangeReason = "press" | "select-all" | "imperative"
type DataTablePageChangeReason =
  | "previous-press"
  | "next-press"
  | "first-press"
  | "last-press"
  | "item-press"
  | "imperative"

type DataTableItem = { value: string; label: string }

type DataTableOptions = {
  sortableColumns?: string[]
  rowItems?: DataTableItem[]
  pageCount?: number
  sort?: DataTableSort | null
  defaultSort?: DataTableSort | null
  onSortChange?: (sort: DataTableSort | null, details: ChangeDetails<DataTableSortChangeReason>) => void
  selection?: readonly string[]
  defaultSelection?: readonly string[]
  onSelectionChange?: (selection: string[], details: ChangeDetails<DataTableSelectionChangeReason>) => void
  page?: number
  defaultPage?: number
  onPageChange?: (page: number, details: ChangeDetails<DataTablePageChangeReason>) => void
  controller?: DataTableController
}

interface DataTableController {
  sortBy: (
    columnId: string | null,
    direction?: SortDirection,
    options?: ChangeOptions<DataTableSortChangeReason>,
  ) => boolean | undefined
  setSelection: (ids: string[], options?: ChangeOptions<DataTableSelectionChangeReason>) => boolean | undefined
  /**
   * Checks (`true`) or unchecks (`false`) rows on top of the latest selection, including one an earlier call chose
   * that hasn't rendered yet. Without `checked`, one row flips and several are checked unless all already are.
   */
  toggleRows: (
    ids: readonly string[],
    checked?: boolean,
    options?: ChangeOptions<DataTableSelectionChangeReason>,
  ) => boolean | undefined
  setPage: (page: number, options?: ChangeOptions<DataTablePageChangeReason>) => boolean | undefined
}

function reasonOf<Reason extends string>(options: unknown): { reason: Reason | "imperative"; event?: Event } {
  if (typeof options !== "object" || options === null) return { reason: "imperative" }
  const { reason = "imperative", event } = options as ChangeOptions<Reason>
  return { reason, event: event instanceof Event ? event : undefined }
}

// The agent bridge passes action arguments unchecked, so every action validates its own.
const dataTable = definePrimitive({
  name: "data-table",
  options: {
    sortableColumns: "list",
    rowItems: "list",
    pageCount: "number",
    sort: "value",
    defaultSort: "value",
    onSortChange: "callback",
    selection: "list",
    defaultSelection: "list",
    onSelectionChange: "callback",
    page: "number",
    defaultPage: "number",
    onPageChange: "callback",
    controller: "value",
  },
  state: (options: DataTableOptions) => ({
    sort: options.sort !== undefined ? options.sort : (options.defaultSort ?? null),
    selection: options.selection ?? options.defaultSelection ?? [],
    page: options.page ?? options.defaultPage ?? 1,
  }),
  sync: (options) => ({
    ...(options.sort === undefined ? {} : { sort: options.sort }),
    ...(options.selection === undefined ? {} : { selection: options.selection }),
    ...(options.page === undefined ? {} : { page: options.page }),
  }),
  controlled: ["sort", "selection", "page"],
  api: (context) => {
    const change = createChange(context)
    // A controlled selection reaches the store only once the table renders again, and agent steps run back to back
    // without one: a toggle builds on what the previous call chose while the store still shows the same selection.
    let chosen: { shown: readonly string[]; next: string[] } | null = null
    const latest = () => {
      const shown = context.store.get().selection
      return chosen !== null && chosen.shown === shown ? chosen.next : shown
    }
    const select = (next: string[], options?: ChangeOptions<DataTableSelectionChangeReason>) => {
      const shown = context.store.get().selection
      const changed = change("selection", next, reasonOf(options))
      if (changed !== false) chosen = { shown, next }
      return changed
    }
    return {
      sortBy(columnId: unknown, direction?: unknown, options?: ChangeOptions<DataTableSortChangeReason>) {
        if (columnId === null) return change("sort", null, reasonOf(options))
        const sortable = context.options().sortableColumns ?? []
        if (typeof columnId !== "string" || !sortable.includes(columnId)) {
          throw new RangeError(`Can't sort by "${String(columnId)}". Sortable columns: ${sortable.join(", ")}.`)
        }
        const current = context.store.get().sort
        const next: SortDirection =
          direction === "ascending" || direction === "descending"
            ? direction
            : current?.columnId === columnId && current.direction === "ascending"
              ? "descending"
              : "ascending"
        return change("sort", { columnId, direction: next }, reasonOf(options))
      },
      setSelection(ids: unknown, options?: ChangeOptions<DataTableSelectionChangeReason>) {
        const known = new Set((context.options().rowItems ?? []).map((item) => item.value))
        if (!Array.isArray(ids) || ids.some((id) => typeof id !== "string" || !known.has(id))) {
          throw new RangeError("setSelection takes a list of row ids from the table.")
        }
        return select([...new Set(ids as string[])], options)
      },
      toggleRows(ids: readonly string[], checked?: boolean, options?: ChangeOptions<DataTableSelectionChangeReason>) {
        const current = latest()
        const check = checked ?? !ids.every((id) => current.includes(id))
        return select(toggleIds(current, ids, check), options)
      },
      setPage(page: unknown, options?: ChangeOptions<DataTablePageChangeReason>) {
        const pageCount = context.options().pageCount ?? 1
        if (typeof page !== "number" || !Number.isInteger(page) || page < 1 || page > pageCount) {
          throw new RangeError(`setPage takes a page from 1 to ${pageCount}.`)
        }
        return change("page", page, reasonOf(options))
      },
      rows: () => context.options().rowItems ?? [],
    }
  },
  slots: (slot) => ({
    root: slot({
      role: "region",
      attrs: (state) => ({
        "data-sorted": state.sort ? "" : undefined,
        "data-selected": state.selection.length > 0 ? "" : undefined,
      }),
    }),
  }),
  agent: { actions: ["sortBy", "setSelection", "setPage"], items: (api) => api.rows() },
})

function createDataTableController() {
  return createController<DataTableController>()
}

export { createDataTableController, dataTable }
export type {
  DataTableController,
  DataTableItem,
  DataTableOptions,
  DataTablePageChangeReason,
  DataTableSelectionChangeReason,
  DataTableSortChangeReason,
}

"use client"

import type { ChangeDetails } from "@ui-sdk/core"
import type { ReactNode } from "react"
import { ChevronDownIcon, ChevronUpIcon, ChevronsUpDownIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Checkbox, CheckboxIndicator, type CheckedState } from "@/components/ui/checkbox"
import type {
  DataTableController,
  DataTablePageChangeReason,
  DataTableSelectionChangeReason,
  DataTableSortChangeReason,
} from "@/components/ui/data-table-primitive"
import { Pagination } from "@/components/ui/pagination"
import { TableHead } from "@/components/ui/table"
import type { DataTableSort, SortDirection, SortValue } from "@/lib/data-table-model"
import { cn } from "@/lib/utils"
import type { Virtualize } from "@/components/ui/virtual-rows"

type DataTableAlign = "start" | "center" | "end"

type DataTableColumn<Row> = {
  id: string
  header: ReactNode
  cell: (row: Row) => ReactNode
  sortValue?: (row: Row) => SortValue
  /** The field a server sorts by, in `manual` mode: the column sorts without a `sortValue`. */
  sortField?: string
  align?: DataTableAlign
  /** Wraps the column's cells onto more lines; by default they stay on one line, cut with an ellipsis and a tooltip. */
  wrap?: boolean
  /** Classes for every body cell of the column, such as a width. */
  cellClassName?: string
  /** Classes for the column's header cell. */
  headerClassName?: string
}

type DataTableLabels = {
  sortBy: (header: string) => string
  selectAll: string
  selectRow: (rowLabel: string) => string
  previousPage: string
  nextPage: string
  pageStatus: (page: number, pageCount: number) => string
  /** A secondary sort's place, read after the sort button's name: "sorted second". */
  sortRank: (rank: number) => string
}

const ordinals = ["first", "second", "third", "fourth", "fifth"]

const dataTableLabels: DataTableLabels = {
  sortBy: (header) => `Sort by ${header}`,
  selectAll: "Select all rows on this page",
  selectRow: (rowLabel) => `Select ${rowLabel}`,
  previousPage: "Previous page",
  nextPage: "Next page",
  pageStatus: (page, pageCount) => `Page ${page} of ${pageCount}`,
  sortRank: (rank) => `sorted ${ordinals[rank - 1] ?? `${String(rank)}th`}`,
}

type DataTablePageOptions = { reason?: DataTablePageChangeReason; event?: Event }

type DataTablePaginationProps = {
  page: number
  pageCount: number
  pageSize: number
  total: number
  onPageChange: (page: number, options?: DataTablePageOptions) => void
}

function SortIcon({ direction }: { direction?: SortDirection }) {
  if (direction === "ascending") return <ChevronUpIcon />
  if (direction === "descending") return <ChevronDownIcon />
  return <ChevronsUpDownIcon />
}

/** A sort after the first: its header shows the direction and its place; only the first sets `aria-sort`. */
type DataTableSecondarySort = { direction: SortDirection; rank: number }

function DataTableHeaderCell<Row>({
  column,
  sort,
  sortable,
  secondary,
  labels,
  onSort,
}: {
  column: DataTableColumn<Row>
  sort: DataTableSort | null
  sortable: boolean
  secondary?: DataTableSecondarySort
  labels: Pick<DataTableLabels, "sortBy" | "sortRank">
  onSort: (event: MouseEvent) => void
}) {
  const primary = sort?.columnId === column.id ? sort.direction : undefined
  const header = typeof column.header === "string" ? column.header : column.id
  // oxlint-disable-next-line shadcn/require-static-classes -- the column's own classes, passed through like className
  const headerClassName = cn("data-[align=center]:text-center data-[align=end]:text-end", column.headerClassName)
  const name = secondary ? `${labels.sortBy(header)}, ${labels.sortRank(secondary.rank)}` : labels.sortBy(header)
  return (
    <TableHead
      scope="col"
      aria-sort={sortable ? (primary ?? "none") : undefined}
      data-align={column.align}
      className={headerClassName}
    >
      {sortable ? (
        <Button
          variant="ghost"
          size="sm"
          aria-label={name}
          render={(part) => <button {...part} data-slot="data-table-sort" />}
          data-align={column.align}
          className="-mx-(--item-padding-x) gap-inline px-(--item-padding-x) text-foreground data-[align=end]:flex-row-reverse [&_svg]:size-3.5"
          onClick={(event) => onSort(event.nativeEvent)}
        >
          {column.header}
          <SortIcon direction={primary ?? secondary?.direction} />
          {secondary && (
            <span aria-hidden="true" className="text-caption text-muted-foreground tabular-nums">
              {secondary.rank}
            </span>
          )}
        </Button>
      ) : (
        column.header
      )}
    </TableHead>
  )
}

function DataTableCheckbox({
  label,
  checked,
  disabled,
  onChange,
  tabIndex,
}: {
  label: string
  checked: CheckedState
  disabled?: boolean
  onChange: (checked: boolean, event?: Event) => void
  /** -1 inside a cell that holds the tab stop itself. */
  tabIndex?: number
}) {
  return (
    <Checkbox
      // The part writes its own tabindex over a prop's; the rendered element's wins.
      render={tabIndex === undefined ? undefined : (part) => <button {...part} tabIndex={tabIndex} />}
      aria-label={label}
      checked={checked}
      disabled={disabled}
      onCheckedChange={(next, details) => onChange(next === true, details.event)}
    >
      <CheckboxIndicator />
    </Checkbox>
  )
}

function DataTablePagination({
  page,
  pageCount,
  onPageChange,
  labels,
}: DataTablePaginationProps & { labels: Pick<DataTableLabels, "previousPage" | "nextPage" | "pageStatus"> }) {
  return (
    <div data-slot="data-table-pagination" className="flex flex-wrap items-center justify-end gap-items">
      <span className="text-sm text-muted-foreground tabular-nums" aria-live="polite">
        {labels.pageStatus(page, pageCount)}
      </span>
      <Pagination
        page={page}
        pageCount={pageCount}
        onPageChange={(next, details) => onPageChange(next, { reason: details.reason, event: details.event })}
        labels={{ previous: labels.previousPage, next: labels.nextPage }}
        className="w-auto"
      />
    </div>
  )
}

export { DataTableCheckbox, DataTableHeaderCell, dataTableLabels, DataTablePagination }
type DataTableProps<Row> = {
  label: string
  rows: readonly Row[]
  columns: readonly DataTableColumn<Row>[]
  getRowId: (row: Row) => string
  getRowLabel?: (row: Row) => string
  sort?: DataTableSort | null
  defaultSort?: DataTableSort | null
  onSortChange?: (sort: DataTableSort | null, details: ChangeDetails<DataTableSortChangeReason>) => void
  selectable?: boolean
  selection?: readonly string[]
  defaultSelection?: readonly string[]
  onSelectionChange?: (selection: string[], details: ChangeDetails<DataTableSelectionChangeReason>) => void
  pageSize?: number
  /**
   * The server sorts and pages: `rows` is the current page as given, sort and page changes are only reported, and
   * `pageCount` (or `total` with `pageSize`) sets the pages. Columns sort by `sortField`.
   */
  manual?: boolean
  /** Every row on the server, in `manual` mode. */
  total?: number
  /** The number of pages in `manual` mode; wins over `total`. */
  pageCount?: number
  /** The sorts after `sort`, in `manual` mode: each header shows its place. */
  secondarySorts?: readonly DataTableSort[]
  /** The rows are being refreshed: `aria-busy` on the table while the current rows stay. */
  busy?: boolean
  page?: number
  defaultPage?: number
  onPageChange?: (page: number, details: ChangeDetails<DataTablePageChangeReason>) => void
  renderPagination?: (props: DataTablePaginationProps) => ReactNode
  loading?: boolean
  loadingRows?: number
  empty?: ReactNode
  labels?: Partial<DataTableLabels>
  controller?: DataTableController
  /** Enter on a focused row, or on a cell with `navigation="cells"`. */
  onRowOpen?: (row: Row) => void
  /**
   * What the keys move between. `"rows"` (default): rows are one tab stop, the arrows or j/k move, Home/End and the
   * page keys jump. `"cells"`: the cells are, as in a spreadsheet; ←/→ move along a row, ↑/↓ keep the column,
   * Home/End reach a row's ends and Ctrl/⌘ with them the table's corners, Space selects the row.
   */
  navigation?: "rows" | "cells"
  /** `"auto"` (default) renders only the rows in view past 200 rows. Bound the table's height to scroll inside it. */
  virtualize?: Virtualize
  /** A row's estimated height in px before it is measured. */
  estimateSize?: number
  className?: string
  tableClassName?: string
}

export type {
  DataTableSecondarySort,
  DataTableAlign,
  DataTableColumn,
  DataTableLabels,
  DataTablePageOptions,
  DataTablePaginationProps,
  DataTableProps,
}

"use client"

import { memo, useCallback, type ReactElement, type ReactNode } from "react"

import { DataTableCheckbox, type DataTableColumn } from "@/components/ui/data-table-parts"
import { NavigableCell, useCellNavigationActive } from "@/components/ui/cell-navigation"
import { NavigableRow } from "@/components/ui/row-navigation"
import { Empty } from "@/components/ui/empty"
import { Skeleton } from "@/components/ui/skeleton"
import { TableCell, TableRow } from "@/components/ui/table"
import { cn } from "@/lib/utils"

// Plain values and stable callbacks, so `memo` keeps a row as it is while the table re-renders for a scroll, a
// sort or another row's selection.
type DataTableRowProps<Row> = {
  row: Row
  id: string
  columns: readonly DataTableColumn<Row>[]
  /** The checkbox's name; without it the row has no checkbox. */
  selectLabel?: string
  selected?: boolean
  /** Checks or unchecks the row by id; undefined `checked` flips it. */
  onToggle?: (id: string, checked?: boolean, event?: Event) => void
  /** The row's place among all rows, while the table is virtualized. */
  index?: number
  /** The row's place among the rows shown, for cell navigation. */
  position: number
  /** The virtualizer's ref for a row; it returns the cleanup that stops measuring. */
  measure?: (node: HTMLElement | null) => (() => void) | undefined
}

// The focus ring sits inside the row: a table row draws no box-shadow, and its outline would be clipped by the scroller.
const rowClassName =
  "scroll-mt-(--control-height) outline-none data-selected:bg-muted focus-visible:bg-muted/70 focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring"

// The cell's focus ring sits inside it, like the row's.
const cellClassName = "outline-none focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring"

const DataTableRow = memo(function DataTableRow<Row>(props: DataTableRowProps<Row>) {
  const cells = useCellNavigationActive()
  if (cells) return <DataTableRowElement {...props} cells />
  return <NavigableRow id={props.id} render={<DataTableRowElement {...props} />} />
}) as <Row>(props: DataTableRowProps<Row>) => ReactNode

function assignRef(ref: unknown, node: HTMLElement | null) {
  if (typeof ref === "function") return (ref as (node: HTMLElement | null) => unknown)(node)
  if (ref && typeof ref === "object") (ref as { current: unknown }).current = node
}

// Rendered by NavigableRow, which passes the roving tab stop's ref and handlers along with the row's own props.
function DataTableRowElement<Row>({
  row,
  id,
  columns,
  selectLabel,
  selected = false,
  onToggle,
  index,
  position,
  measure,
  cells = false,
  ref,
  ...props
}: DataTableRowProps<Row> & { ref?: unknown; cells?: boolean } & Record<string, unknown>) {
  const rowRef = useCallback(
    (node: HTMLTableRowElement | null) => {
      const cleanup = assignRef(ref, node)
      const unmeasure = measure?.(node)
      return () => {
        if (typeof unmeasure === "function") unmeasure()
        if (typeof cleanup === "function") cleanup()
        else assignRef(ref, null)
      }
    },
    [ref, measure],
  )
  // Cells join the table's cell navigation only in that mode, so a row-mode row renders no wrapper per cell.
  const cellAt = (col: number, cell: ReactElement) =>
    cells ? <NavigableCell key={cell.key ?? col} row={position} col={col} render={cell} /> : cell
  return (
    <TableRow
      {...props}
      ref={rowRef}
      data-index={index}
      aria-rowindex={index === undefined ? undefined : index + 2}
      data-row-id={id}
      data-selected={selected ? "" : undefined}
      className={rowClassName}
    >
      {selectLabel !== undefined &&
        cellAt(
          0,
          <TableCell className="w-0">
            <DataTableCheckbox
              label={selectLabel}
              checked={selected}
              tabIndex={cells ? -1 : undefined}
              onChange={(checked, event) => onToggle?.(id, checked, event)}
            />
          </TableCell>,
        )}
      {columns.map((column, col) =>
        cellAt(
          col + (selectLabel === undefined ? 0 : 1),
          <TableCell
            key={column.id}
            data-align={column.align}
            wrap={column.wrap}
            className={cn(
              "data-[align=center]:text-center data-[align=end]:text-end",
              cells && cellClassName,
              column.cellClassName,
            )}
          >
            {column.cell(row)}
          </TableCell>,
        ),
      )}
    </TableRow>
  )
}

function DataTableGapRow({ columns, size, children }: { columns: number; size: number; children?: ReactNode }) {
  return (
    <tr aria-hidden="true" data-slot="data-table-gap" style={{ height: size }}>
      <td colSpan={columns} className="p-0">
        {children}
      </td>
    </tr>
  )
}

function DataTableEmptyRow({ columns, children }: { columns: number; children?: ReactNode }) {
  return (
    <TableRow className="hover:bg-transparent">
      <TableCell colSpan={columns} className="max-w-none">
        {children !== undefined && <Empty className="border-0">{children}</Empty>}
      </TableCell>
    </TableRow>
  )
}

function DataTableLoadingRows({ rows, columns }: { rows: number; columns: number }) {
  return Array.from({ length: rows }, (_, row) => (
    <TableRow key={`loading-${row}`} data-slot="data-table-loading-row" className="hover:bg-transparent">
      {Array.from({ length: columns }, (_cell, column) => (
        <TableCell key={column}>
          {/* One line of text high, like the rows that replace it, so the table doesn't change height. */}
          <div className="flex h-lh items-center">
            <Skeleton className="h-4 w-full max-w-40" />
          </div>
        </TableCell>
      ))}
    </TableRow>
  ))
}

export { DataTableEmptyRow, DataTableGapRow, DataTableLoadingRows, DataTableRow }
export type { DataTableRowProps }

"use client"

import { createParts } from "@ui-sdk/react/primitive"
import { useCallback, useMemo, useState } from "react"

import {
  DataTableCheckbox,
  DataTableHeaderCell,
  dataTableLabels,
  DataTablePagination,
  type DataTableColumn,
  type DataTableLabels,
  type DataTablePageOptions,
  type DataTablePaginationProps,
  type DataTableProps,
} from "@/components/ui/data-table-parts"
import { createDataTableController, dataTable } from "@/components/ui/data-table-primitive"
import { DataTableEmptyRow, DataTableGapRow, DataTableLoadingRows, DataTableRow } from "@/components/ui/data-table-row"
import { CellNavigationProvider, useCellNavigation } from "@/components/ui/cell-navigation"
import { RowNavigationProvider, useRowNavigation } from "@/components/ui/row-navigation"
import { Table, TableBody, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import {
  clampPage,
  pageCountOf,
  paginate,
  selectionState,
  sortRows,
  type DataTableSort,
  type SortDirection,
  type SortValue,
} from "@/lib/data-table-model"
import { cn } from "@/lib/utils"
import { useVirtualRows } from "@/components/ui/virtual-rows"

const { Root: DataTableRoot } = createParts(dataTable, { root: "div" })

function useMirror<Value>(controlled: Value | undefined, initial: Value) {
  const [own, setOwn] = useState(initial)
  return [controlled === undefined ? own : controlled, setOwn] as const
}

// Stable between renders, so a virtualized table's find-in-page stubs re-render only when the rows change.
function useVisibleRows<Row>(
  rows: readonly Row[],
  columns: DataTableProps<Row>["columns"],
  sort: DataTableSort | null,
  page: number,
  pageSize: number | undefined,
  manual: boolean,
) {
  return useMemo(() => {
    if (manual) return rows
    const sortValue = columns.find((column) => column.id === sort?.columnId)?.sortValue
    return paginate(sortRows(rows, sort, sortValue), page, pageSize).rows
  }, [rows, columns, sort, page, pageSize, manual])
}

function isSortable<Row>(column: DataTableColumn<Row>, manual: boolean) {
  return column.sortValue !== undefined || (manual && column.sortField !== undefined)
}

function manualPageCount(pageCount: number | undefined, total: number | undefined, pageSize: number | undefined) {
  if (pageCount !== undefined) return Math.max(1, Math.trunc(pageCount))
  return total === undefined ? 1 : pageCountOf(total, pageSize)
}

function DataTable<Row>({
  label,
  rows,
  columns,
  getRowId,
  getRowLabel = getRowId,
  selectable = false,
  pageSize,
  manual = false,
  total,
  pageCount: pageCountProp,
  secondarySorts,
  busy = false,
  renderPagination,
  loading = false,
  loadingRows = 5,
  empty,
  labels: labelOverrides,
  controller: controllerProp,
  onRowOpen,
  navigation: keys = "rows",
  virtualize = "auto",
  estimateSize = 41,
  className,
  tableClassName,
  ...state
}: DataTableProps<Row>) {
  const labels = { ...dataTableLabels, ...labelOverrides }
  const [ownController] = useState(createDataTableController)
  const controller = controllerProp ?? ownController
  const [sort, setSort] = useMirror(state.sort, state.defaultSort ?? null)
  const [selection, setSelection] = useMirror(state.selection, state.defaultSelection ?? [])
  const [requestedPage, setPage] = useMirror(state.page, state.defaultPage ?? 1)

  const pageCount = manual ? manualPageCount(pageCountProp, total, pageSize) : pageCountOf(rows.length, pageSize)
  const page = clampPage(requestedPage, pageCount)
  const visible = useVisibleRows(rows, columns, sort, page, pageSize, manual)
  const visibleIds = useMemo(() => visible.map(getRowId), [visible, getRowId])
  const selected = new Set(selection)
  const pageSelection = selectionState(visibleIds, selected)
  const rowItems = rows.map((row) => ({
    value: getRowId(row),
    label: getRowLabel(row),
  }))
  const columnCount = columns.length + (selectable ? 1 : 0)
  const indexOf = new Map(visibleIds.map((id, index) => [id, index]))

  const keyAt = useCallback((index: number) => visibleIds[index] ?? String(index), [visibleIds])
  const textAt = useCallback(
    (index: number) => (visible[index] === undefined ? "" : getRowLabel(visible[index])),
    [visible, getRowLabel],
  )
  const { anchor, ...virtual } = useVirtualRows({
    count: loading ? 0 : visible.length,
    findable: textAt,
    virtualize,
    estimateSize,
    getKey: keyAt,
  })

  // Stable, so a memoized row re-renders only when its own row, selection or position changes.
  const toggleRow = useCallback(
    (id: string, checked?: boolean, event?: Event) => controller.toggleRows([id], checked, { reason: "press", event }),
    [controller],
  )
  const navigation = useRowNavigation({
    ids: visibleIds,
    onOpen: onRowOpen
      ? (id) => {
          const index = indexOf.get(id)
          if (index !== undefined && visible[index] !== undefined) onRowOpen(visible[index])
        }
      : undefined,
    onToggle: selectable ? (id, event) => toggleRow(id, undefined, event) : undefined,
    reveal: (id) => {
      const index = indexOf.get(id)
      if (index !== undefined) virtual.scrollToIndex(index)
    },
  })

  const cells = useCellNavigation({
    rows: visible.length,
    cols: columnCount,
    reveal: (index) => virtual.scrollToIndex(index),
    onOpen: onRowOpen
      ? ({ row }) => {
          if (visible[row] !== undefined) onRowOpen(visible[row])
        }
      : undefined,
    onToggle: selectable
      ? ({ row }, event) => {
          const id = visibleIds[row]
          if (id !== undefined) toggleRow(id, undefined, event)
        }
      : undefined,
  })

  const pagination: DataTablePaginationProps = {
    page,
    pageCount,
    pageSize: pageSize ?? rows.length,
    total: manual ? (total ?? rows.length) : rows.length,
    onPageChange: (next: number, options?: DataTablePageOptions) =>
      controller.setPage(clampPage(next, pageCount), options),
  }

  return (
    <DataTableRoot
      aria-label={label}
      controller={controller}
      sortableColumns={columns.filter((column) => isSortable(column, manual)).map((column) => column.id)}
      rowItems={rowItems}
      pageCount={pageCount}
      sort={sort}
      onSortChange={(next, details) => {
        state.onSortChange?.(next, details)
        if (!details.canceled) setSort(next)
      }}
      selection={selection}
      onSelectionChange={(next, details) => {
        state.onSelectionChange?.(next, details)
        if (!details.canceled) setSelection(next)
      }}
      page={page}
      onPageChange={(next, details) => {
        state.onPageChange?.(next, details)
        if (!details.canceled) setPage(next)
      }}
      className={cn("flex w-full flex-col gap-items", className)}
    >
      <Table
        role={keys === "cells" ? "grid" : undefined}
        aria-label={label}
        aria-busy={loading || busy || undefined}
        aria-rowcount={virtual.enabled ? visible.length + 1 : undefined}
        containerClassName="min-h-0"
        className={tableClassName}
      >
        <TableHeader className={cn(virtual.enabled && "[&_th]:sticky [&_th]:top-0 [&_th]:z-10 [&_th]:bg-background")}>
          <TableRow className="hover:bg-transparent">
            {selectable && (
              <TableHead scope="col" className="w-0">
                <DataTableCheckbox
                  label={labels.selectAll}
                  disabled={loading || visibleIds.length === 0}
                  checked={pageSelection === "some" ? "indeterminate" : pageSelection === "all"}
                  onChange={(checked, event) =>
                    controller.toggleRows(visibleIds, checked, {
                      reason: "select-all",
                      event,
                    })
                  }
                />
              </TableHead>
            )}
            {columns.map((column) => {
              const rank = secondarySorts?.findIndex((secondary) => secondary.columnId === column.id) ?? -1
              const secondary = rank === -1 ? undefined : secondarySorts?.[rank]
              return (
                <DataTableHeaderCell
                  key={column.id}
                  column={column}
                  sort={sort}
                  sortable={isSortable(column, manual)}
                  secondary={
                    secondary && {
                      direction: secondary.direction,
                      rank: rank + 2,
                    }
                  }
                  labels={labels}
                  onSort={(event) =>
                    controller.sortBy(column.id, undefined, {
                      reason: "item-press",
                      event,
                    })
                  }
                />
              )
            })}
          </TableRow>
        </TableHeader>
        <TableBody ref={anchor} className={cn(virtual.enabled && "relative")}>
          {loading ? (
            <DataTableLoadingRows rows={loadingRows} columns={columnCount} />
          ) : visible.length === 0 ? (
            <DataTableEmptyRow columns={columnCount}>{empty}</DataTableEmptyRow>
          ) : (
            <RowNavigationProvider handle={navigation}>
              <CellNavigationProvider handle={keys === "cells" ? cells : null}>
                {virtual.segments.map((segment) => {
                  if (segment.type === "gap") {
                    return <DataTableGapRow key={segment.key} columns={columnCount} size={segment.size} />
                  }
                  const row = visible[segment.index]
                  const id = visibleIds[segment.index]
                  if (row === undefined || id === undefined) return null
                  return (
                    <DataTableRow
                      key={id}
                      row={row}
                      id={id}
                      columns={columns}
                      index={virtual.enabled ? segment.index : undefined}
                      position={segment.index}
                      measure={virtual.measureElement}
                      selectLabel={selectable ? labels.selectRow(getRowLabel(row)) : undefined}
                      selected={selected.has(id)}
                      onToggle={selectable ? toggleRow : undefined}
                    />
                  )
                })}
              </CellNavigationProvider>
            </RowNavigationProvider>
          )}
        </TableBody>
      </Table>
      {pageSize !== undefined &&
        pageCount > 1 &&
        (renderPagination ? renderPagination(pagination) : <DataTablePagination {...pagination} labels={labels} />)}
    </DataTableRoot>
  )
}

export { createDataTableController, DataTable, dataTableLabels }
export type { DataTableColumn, DataTableLabels, DataTablePaginationProps, DataTableProps }
export type { DataTableSort, SortDirection, SortValue }

import { byCell, createGridFocus, definePrimitive, selects, type GridCell } from "@ui-sdk/core"

type CellNavigationOptions = {
  rows: number
  cols: number
  /** How many rows Page Up and Page Down move: about as many as show. */
  pageSize?: number
  /** Brings a row that isn't rendered into view, so focus can follow once its cell renders. */
  reveal?: (row: number) => void
  /** Enter on a cell. */
  onOpen?: (cell: GridCell, event: KeyboardEvent) => void
  /** Space on a cell, where rows can be selected. */
  onToggle?: (cell: GridCell, event: KeyboardEvent) => void
}

const defaultPageSize = 10

/**
 * One tab stop for a table's cells, on UI SDK's grid focus: the arrows move by cell (Left and Right follow the text
 * direction), Home/End to a row's ends and with Ctrl/⌘ to the table's corners, Page Up/Down by `pageSize`. A cell
 * that isn't rendered is revealed first. Enter and Space go to `onOpen` and `onToggle`. A move changes two cells.
 */
const cellNavigation = definePrimitive({
  name: "cell-navigation",
  options: {
    rows: "number",
    cols: "number",
    pageSize: "number",
    reveal: "callback",
    onOpen: "callback",
    onToggle: "callback",
  },
  state: (_options: CellNavigationOptions) => ({
    active: null as GridCell | null,
  }),
  api: (context) => {
    const grid = createGridFocus(context, {
      key: "active",
      rows: () => context.options().rows,
      cols: () => context.options().cols,
      pageSize: () => context.options().pageSize ?? defaultPageSize,
      reveal: (cell) => context.options().reveal?.(cell.row),
    })
    return {
      grid,
      keydown(event: KeyboardEvent, el: HTMLElement, cell: GridCell) {
        if (event.defaultPrevented || event.target !== el) return
        if (grid.keydown(event)) {
          event.preventDefault()
          return
        }
        if (event.altKey || event.ctrlKey || event.metaKey) return
        const { onOpen, onToggle } = context.options()
        if (event.key === "Enter" && onOpen) {
          event.preventDefault()
          onOpen(cell, event)
        } else if (event.key === " " && onToggle) {
          event.preventDefault()
          onToggle(cell, event)
        }
      },
      active: () => context.store.get().active,
    }
  },
  slots: (slot) => ({
    root: slot({}),
    // `id` tells the cells apart: unique in the page, and stable while the cell stays.
    cell: slot<{ row: number; col: number; id: string }>({
      props: { row: "number", col: "number", id: "string" },
      focus: "roving",
      keys: [
        "ArrowUp",
        "ArrowDown",
        "ArrowLeft",
        "ArrowRight",
        "Home",
        "End",
        "mod+Home",
        "mod+End",
        "PageUp",
        "PageDown",
      ],
      selects: selects({ active: byCell }),
      attrs: (state, { props, api }) => ({
        role: "gridcell",
        tabindex: api.grid.tabIndex(state, props),
        "data-active": api.grid.isActive(state, props) ? "" : undefined,
      }),
      on: {
        keydown: (event, { el, api, props }) => {
          if (el) api.keydown(event, el, props)
        },
        pointerdown: (event, { api, props }) => api.grid.focus(props, { reason: "item-press", event }),
        // Focus that arrives another way, like Tab or a script, makes the cell active, so the keys move from it.
        focusin: (event, { api, props }) => {
          const active = api.active()
          if (active?.row !== props.row || active.col !== props.col)
            api.grid.focus(props, { reason: "imperative", event })
        },
      },
      bind: (el, { api, props }) => api.grid.bind(el, props),
    }),
  }),
  // Keys are a people-only accelerator: agents act on rows through the table's own actions.
  agent: { actions: [], shown: () => false },
})

export { cellNavigation }
export type { CellNavigationOptions }

"use client"

import { usePart, usePrimitive, type PrimitiveHandle } from "@ui-sdk/react/primitive"
import { cloneElement, createContext, use, useId, type ReactElement, type ReactNode } from "react"

import { cellNavigation, type CellNavigationOptions } from "@/components/ui/cell-navigation-primitive"

type CellNavigationHandle = PrimitiveHandle<typeof cellNavigation>

const CellNavigationContext = createContext<CellNavigationHandle | null>(null)
const CellIdContext = createContext("")

/** The instance that gives a table's cells one tab stop; pass it to `CellNavigationProvider`. */
function useCellNavigation(options: CellNavigationOptions) {
  return usePrimitive(cellNavigation, options)
}

function CellNavigationProvider({ handle, children }: { handle: CellNavigationHandle | null; children: ReactNode }) {
  const prefix = useId()
  return (
    <CellNavigationContext value={handle}>
      <CellIdContext value={prefix}>{children}</CellIdContext>
    </CellNavigationContext>
  )
}

function NavigableCellPart({
  handle,
  row,
  col,
  render,
}: {
  handle: CellNavigationHandle
  row: number
  col: number
  render: ReactElement
}) {
  const id = `${use(CellIdContext)}-${String(row)}-${String(col)}`
  // The cell keeps its own `data-slot` (`table-cell`), which the part would otherwise replace with its slot's.
  return usePart(
    handle,
    "cell",
    { row, col, id },
    {
      render: (part: Record<string, unknown>) =>
        cloneElement(render as ReactElement<Record<string, unknown>>, { ...part, "data-slot": "table-cell" }),
    },
  )
}

/** Makes `render`, a table cell, the cell at `row` and `col`. Outside a `CellNavigationProvider` it renders unchanged. */
function NavigableCell({ row, col, render }: { row: number; col: number; render: ReactElement }) {
  const handle = use(CellNavigationContext)
  if (!handle) return render
  return <NavigableCellPart handle={handle} row={row} col={col} render={render} />
}

/** Whether cells take the keys here, so rows leave the tab stop to them. */
function useCellNavigationActive() {
  return use(CellNavigationContext) !== null
}

export { CellNavigationProvider, NavigableCell, useCellNavigation, useCellNavigationActive }
export type { CellNavigationHandle, CellNavigationOptions }
